import{_ as t,o as s,c as o,a3 as a}from"./chunks/framework.BtuQOqkX.js";const u=JSON.parse('{"title":"Description and purpose","description":"","frontmatter":{},"headers":[],"relativePath":"description.md","filePath":"description.md"}'),r={name:"description.md"};function i(n,e,d,c,p,l){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="description-and-purpose" tabindex="-1">Description and purpose <a class="header-anchor" href="#description-and-purpose" aria-label="Permalink to &quot;Description and purpose&quot;">​</a></h1><p><strong>gh-docs</strong> is a way to publish a repository&#39;s Markdown documentation as a website. It combines:</p><ul><li><a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a> to turn Markdown into a static website.</li><li>GitHub Actions to build and publish that website to GitHub Pages.</li><li>Pull request previews and tagged documentation versions.</li></ul><p>Keep the docs and the application in one repository, so documentation changes can be reviewed with code changes. The VitePress project and its npm dependencies stay under <code>docs/</code>; Java, Go, and other applications do not need a <code>package.json</code> in their root.</p><p>The publishing workflow updates a <code>gh-pages</code> branch. The current docs are served from the site root, release versions from paths such as <code>/versions/v1.2.3/</code>, and active pull request previews from paths such as <code>/pr-42/</code>. A navigation selector lets readers switch between the versions that are currently published.</p><p>GitHub Pages serves static files, so the published site does not need a running application server. See <a href="./usage.html">Usage</a> to add docs and configure publishing, <a href="./versioning.html">Versioning</a> for the selector and release paths, or <a href="./local-run.html">Local run</a> to preview and build the site on your machine.</p>',6)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
